 "content": "from collections import deque


def transform(grid):
    """Repeat each colored seed's bounding-box motif across its 8-bounded panel."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 8 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colored = [(y, x) for y, x in cells if grid[y][x] not in (0, 8)]
            if not colored:
                continue
            top, bottom = min(y for y, _ in colored), max(y for y, _ in colored)
            left, right = min(x for _, x in colored), max(x for _, x in colored)
            ph, pw = bottom - top + 1, right - left + 1
            motif = [[grid[top + dy][left + dx] for dx in range(pw)] for dy in range(ph)]
            for y, x in cells:
                color = motif[(y - top) % ph][(x - left) % pw]
                if color:
                    out[y][x] = color
    return out


if __name__ == '__main__':
